#!/bin/bash
# =============================================================
#  LIBFT TESTER — Self-contained installer
#  Corre: make (1036 testes) + make check (13 checks) + make leaks
#
#  Uso:
#    Coloca este ficheiro dentro da pasta da Libft e corre:
#      bash libft_install.sh
#
#    Ou indica o caminho explicitamente:
#      bash libft_install.sh /caminho/para/Libft
# =============================================================

RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
CYAN='\033[0;36m'
BOLD='\033[1m'
RESET='\033[0m'

banner() {
    echo -e "${BOLD}${CYAN}"
    echo "╔══════════════════════════════════════════╗"
    echo "║     LIBFT TESTER — Installer v2          ║"
    echo "║  make + make check + make leaks          ║"
    echo "╚══════════════════════════════════════════╝"
    echo -e "${RESET}"
}

sep() {
    echo -e "\n${BOLD}${CYAN}══════════════════════════════════════════${RESET}"
    echo -e "${BOLD}${CYAN}  $1${RESET}"
    echo -e "${BOLD}${CYAN}══════════════════════════════════════════${RESET}\n"
}

banner

# ── Find Libft directory ──────────────────────────────────────
LIBFT_DIR=""
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

if [ -n "$1" ]; then
    LIBFT_DIR="$(cd "$1" && pwd)"
    echo -e "${CYAN}[*] Caminho fornecido: $LIBFT_DIR${RESET}"
else
    # 1. Pasta actual (ficheiro colocado dentro da Libft)
    if [ -f "$SCRIPT_DIR/libft.h" ] || [ -f "$SCRIPT_DIR/Makefile" ]; then
        LIBFT_DIR="$SCRIPT_DIR"
        echo -e "${CYAN}[*] Libft detectada na pasta actual: $LIBFT_DIR${RESET}"
    else
        # 2. Pasta pai (ficheiro ao lado da Libft)
        PARENT="$(dirname "$SCRIPT_DIR")"
        for candidate in Libft libft LIBFT; do
            if [ -d "$PARENT/$candidate" ]; then
                LIBFT_DIR="$PARENT/$candidate"
                echo -e "${CYAN}[*] Libft detectada em: $LIBFT_DIR${RESET}"
                break
            fi
        done
    fi

    if [ -z "$LIBFT_DIR" ]; then
        echo -e "${RED}[KO] Nao foi possivel encontrar a pasta Libft.${RESET}"
        echo ""
        echo "  Opcoes:"
        echo "  1. Coloca este ficheiro DENTRO da pasta Libft e corre:"
        echo "     ${BOLD}bash libft_install.sh${RESET}"
        echo ""
        echo "  2. Indica o caminho:"
        echo "     ${BOLD}bash libft_install.sh /caminho/para/Libft${RESET}"
        exit 1
    fi
fi

if [ ! -f "$LIBFT_DIR/libft.h" ] && [ ! -f "$LIBFT_DIR/Makefile" ]; then
    echo -e "${RED}[KO] '$LIBFT_DIR' nao parece uma Libft (sem libft.h ou Makefile)${RESET}"
    exit 1
fi

# ── Extract tester ────────────────────────────────────────────
INSTALL_DIR="$(dirname "$LIBFT_DIR")/libft_tester"
echo -e "${CYAN}[*] A instalar tester em: $INSTALL_DIR${RESET}"

if [ -d "$INSTALL_DIR" ]; then
    echo -e "${YELLOW}[!] '$INSTALL_DIR' ja existe — a actualizar${RESET}"
    rm -rf "$INSTALL_DIR"
fi

TMPFILE=$(mktemp /tmp/libft_XXXXXX.tar.gz)
base64 -d << 'BASE64_END' > "$TMPFILE"

BASE64_END

if [ $? -ne 0 ] || [ ! -s "$TMPFILE" ]; then
    echo -e "${RED}[KO] Falha ao descodificar o arquivo${RESET}"
    rm -f "$TMPFILE"
    exit 1
fi

tar -xzf "$TMPFILE" -C "$(dirname "$LIBFT_DIR")"
rm -f "$TMPFILE"

# Rename extracted folder to libft_tester
if [ -d "$(dirname "$LIBFT_DIR")/libft_v2" ]; then
    mv "$(dirname "$LIBFT_DIR")/libft_v2" "$INSTALL_DIR"
fi
chmod +x "$INSTALL_DIR/check_manual.sh"

echo -e "${GREEN}[OK] Tester extraido${RESET}"

cd "$INSTALL_DIR"

# ═══════════════════════════════════════════════════════════════
sep "1/3 — TESTES FUNCIONAIS (make)"
# ═══════════════════════════════════════════════════════════════
make LIBFT_DIR="$LIBFT_DIR"
MAKE_EXIT=$?

# ═══════════════════════════════════════════════════════════════
sep "2/3 — VERIFICACOES ESTRUTURAIS (make check)"
# ═══════════════════════════════════════════════════════════════
make check LIBFT_DIR="$LIBFT_DIR"
CHECK_EXIT=$?

# ═══════════════════════════════════════════════════════════════
sep "3/3 — MEMORY LEAKS (make leaks)"
# ═══════════════════════════════════════════════════════════════
if command -v valgrind &>/dev/null; then
    make leaks LIBFT_DIR="$LIBFT_DIR"
    LEAKS_EXIT=$?
else
    echo -e "${YELLOW}[!!] valgrind nao instalado — a saltar make leaks${RESET}"
    echo -e "     Instala com: ${BOLD}sudo apt install valgrind${RESET}"
    LEAKS_EXIT=0
fi

# ═══════════════════════════════════════════════════════════════
sep "RESUMO FINAL"
# ═══════════════════════════════════════════════════════════════

print_status() {
    local label="$1"
    local code="$2"
    if [ "$code" -eq 0 ]; then
        echo -e "  ${GREEN}[OK]${RESET}   $label"
    else
        echo -e "  ${RED}[KO]${RESET}   $label (exit $code)"
    fi
}

print_status "make       — testes funcionais" "$MAKE_EXIT"
print_status "make check — verificacoes estruturais" "$CHECK_EXIT"

if command -v valgrind &>/dev/null; then
    print_status "make leaks — memory leaks" "$LEAKS_EXIT"
else
    echo -e "  ${YELLOW}[!!]${RESET}   make leaks — valgrind nao disponivel"
fi


OVERALL=0
[ "$MAKE_EXIT" -ne 0 ] && OVERALL=1
[ "$CHECK_EXIT" -ne 0 ] && OVERALL=1
[ "$LEAKS_EXIT" -ne 0 ] && OVERALL=1

if [ "$OVERALL" -eq 0 ]; then
    echo -e "${BOLD}${GREEN}  ✓ Tudo passou!${RESET}"
else
    echo -e "${BOLD}${RED}  ✗ Alguns testes falharam — ver acima${RESET}"
fi
echo ""
exit $OVERALL
